      {'metric_id':'SWE_SCOPED_OFFICIAL_RESULTS','axis':'OFFICIAL_EVALUATION','numerator':1,'denominator':1,'unit':'TASK_OUTPUT_PAIR','version':sw['source_revision'],'method':'official _grade original log regrade','code':bind(W/'swebench/run_swe_official_regrade.py'),'evidence':bind(s),'limitations':'One new development case relative to15previous; no tests reexecuted; resolved1; no general quality inference','status':'MEASURED'},
